      commands: {
        // 比较后端引擎版本号，eg: v2.8.0
        compareVersions: (version) => {
          const engineVersion = tech.userInfo?.engine_version
          const engineVersionArr = engineVersion?.split('-') || []
          // ruleVersionArr[0]: 当前引擎版本号
          // version: 需要对比的引擎版本号
          // 不存在当前版本号，返回-1
          // 当前版本号大于需对比的版本号，返回1
          // 当前版本号等于需对比的版本号，返回0
          // 当前版本号小于需对比的版本号，返回-1
          if (!engineVersionArr[0]) return -1
          const arr1 = engineVersionArr[0].replace(/^v/i, '').split('.')
          const arr2 = version.replace(/^v/i, '').split('.')
          const maxLen = Math.max(arr1.length, arr2.length)
          const parseSegments = (arr, maxLen) => {
            return arr.map(Number).concat(Array(maxLen - arr.length).fill(0))
          }
          const segments1 = parseSegments(arr1, maxLen)
          const segments2 = parseSegments(arr2, maxLen)

          for (let i = 0; i < maxLen; i++) {
            if (segments1[i] > segments2[i]) return 1
            if (segments1[i] < segments2[i]) return -1
          }
          return 0
        },
        // 从profile接口获取作用域维度的数据
        getProfileUserInfo: async (user) => {
          window.Tech.needGetInitProfile = true
          let userInfo = window.Tech._cloneDeep(user)
          const vm = tech_app.page.getNode('meta_header_right_tenant_extend')
          if (!userInfo?.installedTenant) {
            let res = await window.Tech.httpMeta({
              data: {
                params: {
                  args: {
                    useDisplayForModel: true,
                    ids: [userInfo.id]
                  },
                  model: 'rbac_user',
                  tag: 'master',
                  service: 'profile',
                  app: 'sie-iidp-iam'
                }
              }
            })
            userInfo = res.data
          }

          //  window.tech?.siteUrl 如果当前访问的是子租户，则清空父租户的作用域
          if (window.tech?.siteUrl && !vm.data?.hasShowTenant) {
            userInfo = {}
          }

          // 如果没有curSgAndRule，则置空installedTenant
          if (!userInfo?.curSgAndRule || !userInfo?.curSgAndInstance?.length) {
            userInfo.curSgAndRule = {}
          }
          if (Object.keys(userInfo?.curSgAndRule)?.length == 0) {
            userInfo.installedTenant = null
          }

          if (userInfo?.installedTenant) {
            // 获取是否全局配置 - 作用域是否单选 - 字符串格式！
            let { multiSg } = userInfo || {}
            if (multiSg === undefined) multiSg = 'true'
            vm.$ds.form.isMultiple = multiSg === 'true'
            const { actionScopeId, valueDataId, actionScopeRuleType } =
              userInfo.curSgAndRule || {}
            // 如果是新版作用域，需显示 规则名称/默认值
            if (actionScopeRuleType === 'DIMENSION_RULE') {
              // 前端过滤defaultInstanceId
              userInfo?.curSgAndInstance?.forEach((item) => {
                // 检查所有指定属性是否都为null
                const allNull =
                  !item.actionDimensionId &&
                  !item.actionDimensionName &&
                  !item.actionScopeId &&
                  !item.actionScopeName
                // 如果所有检查的属性都是null，则将defaultInstanceId设置为null
                if (allNull) {
                  item.defaultInstanceId = null
                }
              })
              // 存储回显值
              vm.$ds.form.curSgAndInstance = userInfo?.curSgAndInstance
              let defaultInstanceId =
                userInfo?.curSgAndInstance?.[0]?.defaultInstanceId ?? ''
              let actionScopeIdV2 =
                userInfo?.curSgAndInstance?.[0]?.actionScopeId ?? actionScopeId
              vm.$ds.form.defaultTreeId = actionScopeIdV2 ?? ''
              // 右上角回显中文拼接
              if (userInfo?.curSgAndInstance.length > 1) {
                // 大于1的作用域则加入;拼接
                vm.$ds.form.curActionScope = userInfo?.curSgAndInstance
                  .map(
                    (item) => `${item.actionScopeId}/${item.defaultInstanceId}`
                  )
                  .join(';')
              } else {
                vm.$ds.form.curActionScope = `${actionScopeIdV2}${
                  defaultInstanceId ? '/' + defaultInstanceId : ''
                }`
              }
            } else {
              vm.$ds.form.curActionScope = `${actionScopeId}${
                valueDataId ? '/' + valueDataId : ''
              }`
              // 回显树的配置
              vm.$ds.form.defaultTreeId = actionScopeId ?? ''
              vm.$ds.form.defaultCheck = [valueDataId]
            }

            let arr = []

            let compareResult = vm.$cmd.compareVersions('v2.8')
            if (userInfo.actionScope) {
              userInfo.actionScope.forEach((item) => {
                if (item.type !== 'TENANT_SG') {
                  if (compareResult > -1) {
                    const { isInstanceSelectAll } = item
                    let isMultiple = isInstanceSelectAll === '0' ? false : true
                    arr.push({
                      ...item,
                      text: item.name,
                      alue: item.id,
                      // isInstanceSelectAll兼容历史数据为null时，显示多选
                      // 多选 = "2" / 全选 = "1" / 单选 = "0"  全选也是多选
                      isMultiple:
                        isInstanceSelectAll === null
                          ? vm.$ds.form.isMultiple
                          : isMultiple
                    })
                  } else {
                    arr.push({ ...item, text: item.name, alue: item.id })
                  }
                }
              })
            }
            vm.$ds.listScopes = arr
            // 判断是否选择的是租户作用域，租户作用域不显示box
            let curSG =
              userInfo?.actionScope?.find(
                (item) => item?.id === actionScopeId
              ) ?? null
            if (arr?.length && curSG?.type !== 'TENANT_SG') {
              vm.data.items[0].display = true
              vm.data._handleVisibilityChange = async () => {
                if (!document.hidden) {
                  // 防抖处理
                  if (vm.data?.isRequest) {
                    return
                  }
                  vm.data.isRequest = true
                  vm.data.timeRequest = setTimeout(() => {
                    vm.data.isRequest = false
                  }, 2000)
                  let res = await window.Tech.httpMeta({
                    data: {
                      params: {
                        args: {
                          useDisplayForModel: true,
                          ids: [tech.userInfo.id]
                        },
                        model: 'rbac_user',
                        tag: 'master',
                        service: 'profile',
                        app: 'sie-iidp-iam'
                      }
                    },
                    showMsg: false
                  })
                  clearTimeout(vm.data.timeRequest)
                  vm.data.isRequest = false
                  if (
                    (tech.userInfo?.curSgAndInstance &&
                      !_.isEqual(
                        res?.data?.curSgAndInstance,
                        tech.userInfo?.curSgAndInstance
                      )) ||
                    (tech.userInfo?.curSgAndRule &&
                      !_.isEqual(
                        res?.data?.curSgAndRule,
                        tech.userInfo?.curSgAndRule
                      ))
                  ) {
                    const dialogCheckToken = tech_app.page.getNode(
                      'check_token_change_dialog_reload_tips'
                    )
                    // 存在提示退出登录的弹窗不，则不用刷新
                    if (!dialogCheckToken?.instance && !window.tech?.siteUrl) {
                      window.ELEMENT.Message.warning(
                        Tech.$t('actionScope.scopeChanged')
                      )
                      setTimeout(() => {
                        window.location.reload()
                      }, 1000)
                    }
                  }
                }
              }
              if (
                process?.env !== 'development' &&
                window.tech?.syncScope !== false
              ) {
                // 鼠标移入浏览器窗口，检查作用域是否有变化
                document.addEventListener(
                  'mouseenter',
                  vm.data._handleVisibilityChange
                )
              }
            } else {
              vm.data.items[0].display = false
            }
            // 存储userInfo
            tenantUserInfo = userInfo
          }
        }
      },
